import numpy as np


def encode_decode(X, W_enc, W_dec):
    X = np.asarray(X, dtype=float)
    Z = X @ np.asarray(W_enc, dtype=float)
    return Z @ np.asarray(W_enc, dtype=float).T


def recon_error(X, X_hat):
    D = np.asarray(X, dtype=float) - np.asarray(X_hat, dtype=float)
    return float((D ** 2).sum(axis=1).mean())

